input.command:
mkdir -p /tmp/probe-other/src && cat > /tmp/probe-other/src/shape.h <<'EOF'
/**
 * \file shape.h
 * \brief Geometry primitives header.
 *
 * This file declares the Shape class and a helper function used to
 * compute scaled areas. Detailed file-level documentation lives here.
 */

#ifndef SHAPE_H
#define SHAPE_H

/**
 * \brief A geometric shape.
 *
 * Detailed description of the Shape class. A Shape has a width and a
 * height and can compute its own area. This paragraph exists to give
 * the detailed-description section some real content.
 */
class Shape {
  public:
    /** \brief Construct a shape. */
    Shape(double w, double h);

    /**
     * \brief Compute the area.
     * \return The area of the shape.
     */
    double area() const;

  private:
    double m_w; ///< The width.
    double m_h; ///< The height.
};

/**
 * \brief Scale the area of a shape.
 *
 * Multiplies the shape's area by a factor.
 *
 * \param s      The shape to measure.
 * \param factor The scaling factor applied to the area.
 * \return The scaled area.
 */
double scaledArea(const Shape &s, double factor);

#endif
EOF
ls -la /tmp/probe-other/src/
